package fraymus.workspace;

import org.json.*;
import java.nio.*;
import java.nio.channels.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;

/** Durable, source-pinned interpretation of036 traces. Original pixel/native histories are untouched. */
final class MetricObservationStore {
    static final String VERSION="metric-observations-037-v1";
    private final WorldObservationStore observations;
    private final WorldLedger worlds;
    private final Path file,lock;
    MetricObservationStore(Path project,WorldObservationStore observations,WorldLedger worlds){this.observations=observations;this.worlds=worlds;file=project.resolve("metric-observations/state.json");lock=file.resolveSibling("state.lock");}
    static String identity(){var s=new StringBuilder(VERSION);for(Class<?> c:new Class<?>[]{MetricObservationStore.class,PlaneCalibration.class})try(var in=c.getResourceAsStream(c.getSimpleName()+".class")){s.append(PerceptionStore.hash(in.readAllBytes()));}catch(Exception e){throw new IllegalStateException(e);}return MeasurementStore.hash(s.toString());}
    private interface Tx<T>{T apply(JSONObject state)throws Exception;}
    private synchronized <T>T access(boolean write,Tx<T> tx)throws Exception{
        Files.createDirectories(file.getParent());
        try(var channel=FileChannel.open(lock,StandardOpenOption.CREATE,StandardOpenOption.WRITE);var held=channel.lock()){
            JSONObject s;
            if(Files.exists(file)){if(Files.size(file)>8_000_000)throw new IllegalStateException("Metric history exceeds8MB; preserve original");var e=new JSONObject(Files.readString(file));s=e.getJSONObject("payload");if(!VERSION.equals(e.getString("version"))||!WorldFrames.hash(s).equals(e.getString("sha256")))throw new IllegalStateException("Metric history checksum changed");}
            else s=new JSONObject().put("clocks",new JSONArray()).put("geometries",new JSONArray()).put("profiles",new JSONArray()).put("evaluations",new JSONArray());
            T result=tx.apply(s);
            if(write){for(String k:s.keySet())if(s.getJSONArray(k).length()>64)throw new IllegalStateException("Metric record capacity64 reached; no pruning");byte[] bytes=new JSONObject().put("version",VERSION).put("sha256",WorldFrames.hash(s)).put("payload",s).toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>8_000_000)throw new IllegalStateException("Metric history capacity reached");Path pending=file.resolveSibling("state.pending.json");try(var out=FileChannel.open(pending,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING,StandardOpenOption.WRITE)){ByteBuffer b=ByteBuffer.wrap(bytes);while(b.hasRemaining())out.write(b);out.force(true);}Files.move(pending,file,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}
            return result;
        }
    }
    static JSONObject find(JSONArray values,String id){for(Object raw:values){var v=(JSONObject)raw;if(v.getString("id").equals(id))return v;}throw new IllegalArgumentException("Unknown metric record");}
    private static JSONObject stamp(JSONObject v){return v.put("id",UUID.randomUUID().toString()).put("createdAt",Instant.now());}
    JSONObject state()throws Exception{return access(false,s->WorldFrames.copy(s).put("version",VERSION).put("scope","Fixed camera and declared plane only; empirical uncertainty is not object recognition,3D reconstruction or native physics authority"));}
    JSONObject clock(JSONObject input)throws Exception{
        SpatialScene.keys(input,"datasetId","seconds","source","cameraKey");var d=observations.dataset(input.getString("datasetId"));var times=input.getJSONArray("seconds");if(times.length()!=d.getJSONArray("frames").length())throw new IllegalArgumentException("One real timestamp per original sampled frame required");
        double prev=-Double.MAX_VALUE;for(Object raw:times){double t=((Number)raw).doubleValue();PlaneCalibration.bounded(t,0,1_000_000);if(t<=prev||prev>=0&&t-prev>5)throw new IllegalArgumentException("Timestamps must strictly increase with gaps up to5seconds");prev=t;}
        if(input.getString("source").isBlank()||input.getString("source").length()>1500||!input.getString("cameraKey").matches("[a-zA-Z0-9_-]{1,80}"))throw new IllegalArgumentException("Declare timing source and fixed camera key");
        var record=WorldFrames.copy(input).put("datasetSha256",d.getString("contentSha256"));return access(true,s->{for(Object raw:s.getJSONArray("clocks")){var old=(JSONObject)raw;if(old.getString("datasetId").equals(d.getString("id"))){var compare=WorldFrames.copy(old);compare.remove("id");compare.remove("createdAt");if(!compare.similar(record))throw new IllegalStateException("Dataset timing/camera binding is immutable; import a new dataset");return WorldFrames.copy(old);}}stamp(record);s.getJSONArray("clocks").put(record);return WorldFrames.copy(record);});
    }
    JSONObject geometry(JSONObject input)throws Exception{var p=new PlaneCalibration(input);return access(true,s->{for(Object raw:s.getJSONArray("geometries")){var old=(JSONObject)raw;if(old.getString("sha256").equals(p.hash()))return WorldFrames.copy(old);}var r=stamp(new JSONObject().put("definition",p.definition()).put("sha256",p.hash()));s.getJSONArray("geometries").put(r);return WorldFrames.copy(r);});}
    private JSONObject clockFor(JSONObject s,String dataset){for(Object raw:s.getJSONArray("clocks")){var c=(JSONObject)raw;if(c.getString("datasetId").equals(dataset))return c;}throw new IllegalStateException("This footage has no measured/source timestamp binding; supply timing before metres/second");}
    JSONObject view(JSONObject input)throws Exception{
        SpatialScene.keys(input,"runId","geometryId","profileId");var run=observations.read(input.getString("runId"));var d=observations.dataset(run.getString("datasetId"));
        return access(false,s->{var c=clockFor(s,d.getString("id"));if(!c.getString("datasetSha256").equals(d.getString("contentSha256")))throw new IllegalStateException("Timed source bytes changed");var g=find(s.getJSONArray("geometries"),input.getString("geometryId"));var plane=new PlaneCalibration(g.getJSONObject("definition"));if(!plane.definition().getString("cameraKey").equals(c.getString("cameraKey")))throw new IllegalStateException("Camera/plane binding differs; do not reuse calibration after camera movement");if(plane.definition().getString("mode").equals("ruler")&&Math.abs(plane.definition().getDouble("imageAspect")-d.getDouble("width")/d.getDouble("height"))>1e-8)throw new IllegalStateException("Ruler image aspect differs from source");JSONObject profile=null;if(!input.optString("profileId").isEmpty()){profile=find(s.getJSONArray("profiles"),input.getString("profileId"));if(!profile.getString("geometrySha256").equals(g.getString("sha256"))||!profile.getString("codeSha256").equals(run.getString("codeSha256"))||!profile.getString("metricCodeSha256").equals(identity()))throw new IllegalStateException("Profile geometry/tracker identity differs");}
            var rows=new JSONArray();var previous=new HashMap<String,double[]>();var heights=new HashMap<String,Double>();for(Object raw:run.getJSONArray("bindings")){var binding=(JSONObject)raw;for(Object o:d.getJSONArray("objects")){var obj=(JSONObject)o;if(obj.getString("key").equals(binding.getString("objectKey")))heights.put(binding.getString("bodyId"),(obj.getJSONArray("box").getDouble(3)-obj.getJSONArray("box").getDouble(1)));}}
            for(Object raw:run.getJSONArray("trace")){var frame=(JSONObject)raw;int ordinal=frame.getInt("ordinal");double sec=c.getJSONArray("seconds").getDouble(ordinal);for(Object o:frame.getJSONArray("objects")){var obj=(JSONObject)o;String body=obj.getString("bodyId");var e=obj.getJSONObject("estimate");var tracker=obj.getJSONObject("tracker");if(e.getBoolean("accepted")&&tracker.has("box")&&!tracker.isNull("box"))heights.put(body,(tracker.getJSONArray("box").getDouble(3)-tracker.getJSONArray("box").getDouble(1)));var pos=e.getJSONArray("position");double x=pos.getDouble(0),y=pos.getDouble(1)+heights.get(body)/2;var row=new JSONObject().put("ordinal",ordinal).put("sourceFrame",frame.getInt("sourceFrame")).put("imageSha256",frame.getString("imageSha256")).put("seconds",sec).put("bodyId",body).put("accepted",e.getBoolean("accepted")).put("trackingStatus",tracker.getString("status")).put("pointImage",new JSONArray(new double[]{x,y}));
                try{if(!plane.inPlane(x,y))throw new IllegalArgumentException("Outside calibrated plane/image region");double[] p=plane.project(x,y);var cov=e.getJSONArray("covariance");double sigma=Math.max(.01,plane.sigma(x,y,cov.getJSONArray(0).getDouble(0),cov.getJSONArray(1).getDouble(0)));double systematic=plane.definition().getDouble("anchorSigmaM")+plane.definition().getDouble("scaleRelativeSigma")*Math.hypot(p[0],p[1]);double radius=(profile==null?2:profile.getDouble("multiplier"))*sigma+systematic;row.put("positionM",new JSONArray(p)).put("sigmaM",sigma).put("radiusM",radius).put("status",e.getBoolean("accepted")?"measured-estimate":"prediction-only");var last=previous.get(body);if(last!=null)row.put("speedMps",Math.hypot(p[0]-last[0],p[1]-last[1])/(sec-last[2]));previous.put(body,new double[]{p[0],p[1],sec});}
                catch(IllegalArgumentException ex){row.put("status","unprojectable").put("reason",ex.getMessage());previous.remove(body);}rows.put(row);}}
            var nativeState=worlds.observe(run.getJSONObject("nativeBinding").getString("worldId"));boolean stale=!nativeState.getString("expectedHash").equals(run.getJSONObject("nativeBinding").getString("expectedHash"));return new JSONObject().put("version",VERSION).put("metricCodeSha256",identity()).put("runId",run.getString("id")).put("datasetId",d.getString("id")).put("runStatus",run.getString("status")).put("runTraceSha256",WorldFrames.hash(new JSONObject().put("trace",run.getJSONArray("trace")))).put("nativeBinding",run.getJSONObject("nativeBinding")).put("nativeStale",stale).put("geometry",g).put("clock",c).put("codeSha256",run.getString("codeSha256")).put("profile",profile==null?JSONObject.NULL:WorldFrames.copy(profile)).put("rows",rows).put("uncertaintyMeaning",profile==null?"Uncalibrated propagated model radius, plus declared anchor/scale error; not probability":"Empirical calibration on correlated reference footage, same fixed camera/plane only; held coverage and width are separate evidence").put("scope","Metres on declared plane, actual supplied source seconds; box bottom centre assumes ground contact. Native verified physics is unchanged.");});
    }
    private static JSONArray residuals(JSONObject view,JSONArray references){if(references.length()<12||references.length()>96)throw new IllegalArgumentException("Provide12..96 independent reference positions (seed excluded)");var out=new JSONArray();var keys=new HashSet<String>();for(Object raw:references){var ref=(JSONObject)raw;SpatialScene.keys(ref,"ordinal","bodyId","positionM");int ordinal=ref.getInt("ordinal");if(ordinal<=0||ordinal!=ref.getDouble("ordinal")||!keys.add(ordinal+":"+ref.getString("bodyId")))throw new IllegalArgumentException("Distinct later frame/body references required");double[] truth=PlaneCalibration.point(ref.getJSONArray("positionM"));JSONObject found=null;for(Object r:view.getJSONArray("rows")){var row=(JSONObject)r;if(row.getInt("ordinal")==ordinal&&row.getString("bodyId").equals(ref.getString("bodyId")))found=row;}if(found==null)throw new IllegalArgumentException("Reference does not match original trace");var score=WorldFrames.copy(ref);if(found.has("positionM")){double error=PlaneCalibration.distance(PlaneCalibration.point(found.getJSONArray("positionM")),truth);score.put("errorM",error).put("sigmaM",found.getDouble("sigmaM")).put("radiusM",found.getDouble("radiusM")).put("covered",error<=found.getDouble("radiusM"));}else score.put("unprojectable",true).put("covered",false);out.put(score);}return out;}
    JSONObject fit(JSONObject input)throws Exception{
        SpatialScene.keys(input,"runId","geometryId","references","source");if(input.getString("source").isBlank()||input.getString("source").length()>1500)throw new IllegalArgumentException("Declare independent reference source");var request=new JSONObject().put("runId",input.getString("runId")).put("geometryId",input.getString("geometryId"));var view=view(request);if(!view.getString("runStatus").equals("completed"))throw new IllegalStateException("Fit only a complete immutable trace");var scores=residuals(view,input.getJSONArray("references"));double[] ratios=new double[scores.length()];for(int i=0;i<scores.length();i++){var r=scores.getJSONObject(i);if(r.optBoolean("unprojectable"))throw new IllegalStateException("Calibration includes unprojectable points; no profile");ratios[i]=r.getDouble("errorM")/r.getDouble("sigmaM");}Arrays.sort(ratios);int rank=Math.min(ratios.length,(int)Math.ceil((ratios.length+1)*.9));double q=Math.max(.01,ratios[rank-1]);if(!Double.isFinite(q)||q>10000)throw new IllegalStateException("Calibration residual scale unbounded");var record=stamp(new JSONObject().put("runId",input.getString("runId")).put("runTraceSha256",view.getString("runTraceSha256")).put("geometryId",input.getString("geometryId")).put("geometrySha256",view.getJSONObject("geometry").getString("sha256")).put("codeSha256",view.getString("codeSha256")).put("metricCodeSha256",identity()).put("multiplier",q).put("targetCoverage",.9).put("rank",rank).put("referenceCount",ratios.length).put("references",input.getJSONArray("references")).put("scores",scores).put("source",input.getString("source")).put("qualification","experimental; calibration-only, no held evaluation guarantee"));return access(true,s->{for(Object raw:s.getJSONArray("profiles")){var old=(JSONObject)raw;if(old.getString("runId").equals(record.getString("runId"))&&old.getString("geometryId").equals(record.getString("geometryId")))throw new IllegalStateException("First calibration is immutable; use a genuinely new calibration run");}s.getJSONArray("profiles").put(record);return WorldFrames.copy(record);});
    }
    JSONObject evaluate(JSONObject input)throws Exception{
        SpatialScene.keys(input,"runId","geometryId","profileId","references","source");if(input.getString("source").isBlank()||input.getString("source").length()>1500)throw new IllegalArgumentException("Declare held reference source");var view=view(new JSONObject().put("runId",input.getString("runId")).put("geometryId",input.getString("geometryId")).put("profileId",input.getString("profileId")));var profile=view.getJSONObject("profile");if(profile.getString("runId").equals(input.getString("runId"))||!view.getString("runStatus").equals("completed"))throw new IllegalArgumentException("Use a separate completed evaluation run");var scores=residuals(view,input.getJSONArray("references"));double error=0,radius=0;int covered=0,missing=0;for(Object raw:scores){var r=(JSONObject)raw;if(r.getBoolean("covered"))covered++;if(r.optBoolean("unprojectable"))missing++;else{error+=r.getDouble("errorM");radius+=r.getDouble("radiusM");}}
        var metrics=new JSONObject().put("referenceCount",scores.length()).put("unprojectable",missing).put("coverage",covered/(double)scores.length()).put("meanErrorM",missing==scores.length()?JSONObject.NULL:error/(scores.length()-missing)).put("meanRadiusM",missing==scores.length()?JSONObject.NULL:radius/(scores.length()-missing));boolean passed=missing==0&&metrics.getDouble("coverage")>=.8&&metrics.getDouble("meanRadiusM")<=1;var record=stamp(new JSONObject().put("runId",input.getString("runId")).put("profileId",input.getString("profileId")).put("runTraceSha256",view.getString("runTraceSha256")).put("source",input.getString("source")).put("scores",scores).put("metrics",metrics).put("passed",passed));return access(true,s->{for(Object raw:s.getJSONArray("evaluations")){var old=(JSONObject)raw;if(old.getString("profileId").equals(record.getString("profileId"))&&old.getString("runId").equals(record.getString("runId")))throw new IllegalStateException("First held evaluation is immutable");}s.getJSONArray("evaluations").put(record);return WorldFrames.copy(record);});
    }
    JSONObject export(JSONObject input)throws Exception{var view=view(input);return new JSONObject().put("schema",VERSION).put("metric",view).put("calibrationHistory",state()).put("originalObservations",observations.export(input.getString("runId")));}
}
